string P;
string S="<+11111>xx<-22222>www<+33333>xx<-44444>www<+55555>xx<-66666>";
char T[100];
strcpy(#T[0], S);
int N=0;
loop()
{
if (regexsearch(1, #P, #T[N], "(?<=<\+)(.+?)(?=>)")==0) break;
messagebox (P);
N=N+regexend(0);
if (regexsearch(1, #P, #T[N], "(?<=<-)(.+?)(?=>)")==0) break;
messagebox (P);
N=N+regexend(0);
}
