strcpy(#T[0], S);
int N=0;
loop()
{
if (regexsearch(1, #P, #T[N], "(?<=<\+)(.+?)(?=>)")==0) break;
messagebox (P);
N=N+regexend(0);
if (regexsearch(1, #P, #T[N], "(?<=<-)(.+?)(?=>)")==0) break;
