{
flag_button[0]--;
scrin();//вызов функции которая выполнится при нажатие
goto a;
}
или
Цитата:
if (flag_button[0]>0)//один раз только не зависимо от кликов
{
flag_button[0]=0;// обнуляем
scrin();//вызов функции которая выполнится при нажатие
}
