mciSendString("set recsound samplespersec 44100", "", 0, 0);
mciSendString("record recsound", "", 0, 0);
pause(5000);//Это время будет записывать
mciSendString("save recsound c:\111.wav", "", 0, 0);
mciSendString("close recsound", "", 0, 0)
