//////////
win aw=window("Наш бот");//Получаем указатель на наше окно
visualwindow(aw, 0, 0, 0, 100, 100, 5, 5 , 100, -1);//Включаем вывод на нашем окне
loop()
{
if (flag_button0[0]==1)
{
flag_button0[0]=0;
disablevisualwindow(0);
sleep(100);
destroydialog(0);
